import React, { useState, useEffect, useRef } from 'react';
import { Box, Typography, Container, Stack, Button, CircularProgress } from '@mui/material';
import { Document, Page, pdfjs } from 'react-pdf';

pdfjs.GlobalWorkerOptions.workerSrc = `${process.env.PUBLIC_URL}/pdf.worker.min.mjs`;

const Portfolio = () => {
  const [dots, setDots] = useState('');
  const [numPages, setNumPages] = useState(null);
  const containerRef = useRef(null);
  const [containerWidth, setContainerWidth] = useState(null);
  const [isReady, setIsReady] = useState(false);

  useEffect(() => {
    const interval = setInterval(() => {
      setDots(prev => {
        if (prev === '...') return '';
        return prev + '.';
      });
    }, 500);

    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (!containerRef.current) return;
    const element = containerRef.current;
    const observer = new ResizeObserver(entries => {
      for (const entry of entries) {
        const width = entry.contentRect.width;
        // Give some padding margin so pages fit nicely
        setContainerWidth(Math.max(0, width - 32));
      }
    });
    observer.observe(element);
    return () => observer.disconnect();
  }, []);

  const onLoadSuccess = ({ numPages: loadedNumPages }) => {
    setNumPages(loadedNumPages);
  };

  const pageRenderReady = () => setIsReady(true);


  return (
    <Container maxWidth="xl" sx={{ py: { xs: 4, sm: 6, md: 8 }, px: { xs: 2, sm: 3, md: 4 } }}>
      <Typography 
        variant="h2" 
        component="h1" 
        sx={{ 
          fontFamily: 'Helvetica, Arial, sans-serif',
          fontWeight: 300,
          letterSpacing: { xs: '0.05em', sm: '0.1em' },
          textTransform: 'uppercase',
          mb: { xs: 3, sm: 4, md: 6 },
          textAlign: 'center',
          fontSize: { xs: '1.8rem', sm: '2.2rem', md: '3.75rem' }
        }}
      >
        Portfolio
      </Typography>

      <Stack direction={{ xs: 'row' }} spacing={2} alignItems="center" justifyContent="flex-end" sx={{ mb: 2 }}>
        <Stack direction="row" spacing={1} justifyContent="flex-end">
          <Button
            variant="contained"
            color="primary"
            href="/portfolio.pdf"
            download
          >
            descargar
          </Button>
        </Stack>
      </Stack>

      <Box ref={containerRef} sx={{
        borderRadius: 0,
        // sin sombra ni borde
        bgcolor: '#fff',
        border: 'none',
        p: { xs: 1, sm: 2 },
        position: 'relative'
      }}>
        <Document
          file="/portfolio.pdf"
          onLoadSuccess={onLoadSuccess}
          loading={
            <Box sx={{ py: 8, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2 }}>
              <CircularProgress size={28} thickness={4} />
              <Typography variant="body1">Cargando PDF{dots}</Typography>
            </Box>
          }
          error={
            <Box sx={{ py: 6, textAlign: 'center' }}>
              <Typography variant="h6" sx={{ mb: 2 }}>No se pudo cargar el PDF.</Typography>
              <Button variant="contained" color="primary" href="/portfolio.pdf" target="_blank" rel="noopener noreferrer">
                Abrir/Descargar Portfolio
              </Button>

            </Box>
          }
        >
          {numPages && containerWidth && (
            <Stack spacing={3} sx={{ alignItems: 'center' }}>
              {Array.from({ length: numPages }, (_, i) => i + 1).map(pageNumber => (
                <Page
                  key={pageNumber}
                  pageNumber={pageNumber}
                  width={Math.min(1600, Math.floor(containerWidth))}
                  renderTextLayer={false}
                  renderAnnotationLayer={false}
                  onRenderSuccess={pageNumber === 1 ? pageRenderReady : undefined}
                />
              ))}
            </Stack>
          )}
        </Document>

        {!isReady && (
          <Box sx={{
            position: 'absolute',
            inset: 0,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            bgcolor: 'rgba(255,255,255,0.6)'
          }}>
            <Stack spacing={2} alignItems="center">
              <CircularProgress size={28} thickness={4} />
              <Typography variant="body2">Preparando vista{dots}</Typography>
            </Stack>
          </Box>
        )}
      </Box>
    </Container>
  );
};

export default Portfolio;

